const API = import.meta.env.VITE_API_URL || 'http://127.0.0.1:8000/api/v1';
type Conversation = {id:string; brand_id:string; customer_name:string; customer_number?:number; email:string; order_id:string; status:string; ignored_by_customer?:boolean; assigned_to:string; created_at:string; updated_at:string; last_message:string; message_count:number};
type Attachment = {id:string;name:string;media_type:string;size:number;url:string};
type Message = {id:number; role:string; content:string; created_at:string; transparency:string|null; attachments?:Attachment[]};
type Stats = {total:number;open:number;waiting:number;human_active:number;ai_active:number;resolved:number;ignored:number};
type SidebarSearchItem = {label:string;section:string;view:string;filter?:string;tab?:string};
const SIDEBAR_SEARCH_ITEMS:SidebarSearchItem[]=[
  {label:'Overview',section:'Workspace',view:'Overview'},
  {label:'Conversations',section:'Workspace',view:'Conversations'},
  {label:'Customers',section:'Workspace',view:'Customers'},
  {label:'AI analytics',section:'Workspace',view:'AI analytics'},
  {label:'Technical Inspector',section:'Workspace',view:'Technical Inspector'},
  {label:'All conversations',section:'Inbox views',view:'Conversations',filter:'all',tab:'All'},
  {label:'Needs attention',section:'Inbox views',view:'Conversations',filter:'waiting',tab:'All'},
  {label:'Human active',section:'Inbox views',view:'Conversations',filter:'human_active',tab:'All'},
  {label:'AI active',section:'Inbox views',view:'Conversations',filter:'ai_active',tab:'All'},
  {label:'Resolved & ignored',section:'Inbox views',view:'Conversations',filter:'archive',tab:'All'},
];
const ago=(s:string)=>{const n=Math.max(0,Math.floor((Date.now()-new Date(s).getTime())/60000));return n<1?'now':n<60?`${n}m`:`${Math.floor(n/60)}h`};
const initials=(s='Guest')=>s.split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase();
const avatar=(key:string)=>{let hash=0;for(let i=0;i<key.length;i++)hash=(hash*31+key.charCodeAt(i))|0;return `avatar tone-${Math.abs(hash)%6}`};

async function request(path:string, token?:string, options:RequestInit={}) {
  const response=await fetch(`${API}${path}`,{...options,credentials:options.credentials||'include',headers:{'Content-Type':'application/json',...(token?{Authorization:`Bearer ${token}`} :{}),...options.headers}});
  if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.detail||`Request failed (${response.status})`)}
  return response.json();
}

const ALLOWED_ATTACHMENT_TYPES=['image/jpeg','image/png','image/gif','image/webp','application/pdf'];
function encodeAttachments(files:File[]){return Promise.all(files.map(file=>new Promise<{name:string;media_type:string;data:string}>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>{const result=String(reader.result||'');resolve({name:file.name,media_type:file.type,data:result.slice(result.indexOf(',')+1)})};reader.onerror=()=>reject(new Error(`Could not read ${file.name}`));reader.readAsDataURL(file)})))}
function mergeAttachmentFiles(existing:File[],added:File[]){if(existing.length+added.length>4)throw new Error('Choose up to 4 files per message.');if(added.some(file=>!ALLOWED_ATTACHMENT_TYPES.includes(file.type)))throw new Error('Attach JPG, PNG, GIF, WEBP images, or PDFs.');if(added.some(file=>file.size>5*1024*1024)||[...existing,...added].reduce((sum,file)=>sum+file.size,0)>10*1024*1024)throw new Error('Each file must be under 5 MB and total attachments under 10 MB.');return [...existing,...added]}

async function customerRequest(path:string, options:RequestInit={}){
  const response=await fetch(API+path,{...options,credentials:'include',headers:{'Content-Type':'application/json',...options.headers}});
  if(!response.ok){const data=await response.json().catch(()=>({}));throw new Error(data.detail||('Request failed ('+response.status+')'))}
  return response.json();
}

